import React from 'react';

const TABS = [
  {
    id: 'home', label: 'Hem',
    icon: (
      <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
        <path d="M3 12L12 4l9 8"/>
        <path d="M5 10v9a1 1 0 001 1h4v-4h4v4h4a1 1 0 001-1v-9"/>
      </svg>
    ),
  },
  {
    id: 'checkin', label: 'Dag',
    icon: (
      <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="9"/>
        <path d="M8 12l3 3 5-5"/>
      </svg>
    ),
  },
  {
    id: 'history', label: 'Logg',
    icon: (
      <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
        <rect x="3" y="4" width="18" height="18" rx="2"/>
        <path d="M16 2v4M8 2v4M3 10h18"/>
        <path d="M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01"/>
      </svg>
    ),
  },
  {
    id: 'breathing', label: 'Andas',
    icon: (
      <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 4c0 0-4 3-4 7s4 5 4 9"/>
        <path d="M12 4c0 0 4 3 4 7s-4 5-4 9"/>
        <path d="M8 11c-2 0-4-1-4-3s2-3 4-3"/>
        <path d="M16 11c2 0 4-1 4-3s-2-3-4-3"/>
      </svg>
    ),
  },
];

export default function Nav({ page, setPage }) {
  return (
    <div style={{
      position: 'fixed', bottom: 28, left: '50%', transform: 'translateX(-50%)',
      zIndex: 300,
      display: 'flex', alignItems: 'center', gap: 0,
      background: 'rgba(20,35,35,0.85)',
      backdropFilter: 'blur(24px)',
      WebkitBackdropFilter: 'blur(24px)',
      borderRadius: 999,
      padding: 8,
      border: '1px solid rgba(255,255,255,0.07)',
      boxShadow: '0 8px 32px rgba(0,0,0,0.2)',
    }}>
      {TABS.map(tab => {
        const active = page === tab.id;
        return (
          <button
            key={tab.id}
            onClick={() => setPage(tab.id)}
            aria-label={tab.label}
            style={{
              width: 52, height: 40, borderRadius: 999,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: active ? 'rgba(255,255,255,0.13)' : 'transparent',
              color: active ? 'rgba(255,255,255,0.92)' : 'rgba(255,255,255,0.28)',
              transition: 'all 0.3s cubic-bezier(0.34,1.4,0.64,1)',
            }}
          >
            {tab.icon}
          </button>
        );
      })}
    </div>
  );
}
